package com.atlasiq.security;
import com.atlasiq.qir.Finding;import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.util.stream.Stream;
@ApplicationScoped public class SecretScanner {private static final List<Pattern>P=List.of(Pattern.compile("(?i)(api[_-]?key|secret|token|password)\\s*[:=]\\s*['\"]?[A-Za-z0-9_./+=-]{16,}"),Pattern.compile("AKIA[0-9A-Z]{16}"),Pattern.compile("-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"));
 public List<Finding> scan(Path root){List<Finding> out=new ArrayList<>();try(Stream<Path>s=Files.walk(root,8)){s.filter(Files::isRegularFile).filter(p->!p.toString().contains(".git")).filter(p->size(p)<1_000_000).forEach(p->{try{int line=0;for(String x:Files.readAllLines(p)){line++;for(Pattern q:P)if(q.matcher(x).find()){out.add(new Finding("security","high","Potential secret detected",root.relativize(p)+":"+line,"secret:"+root.relativize(p)+":"+line));break;}}}catch(Exception ignored){}});}catch(Exception ignored){}return List.copyOf(out);}private long size(Path p){try{return Files.size(p);}catch(Exception e){return Long.MAX_VALUE;}}}
